// CSV for exports (EMP-04): RFC 4180 quoting, and a guard against spreadsheet
// formula injection (a text cell that starts with = + - @ tab or CR is prefixed with
// an apostrophe, as OWASP advises). Pure; used by the dashboard and the Edge Functions.

const FORMULA_START = /^[=+\-@\t\r]/;

/** One cell. Numbers and booleans are written as they are; objects and arrays as JSON. */
export function csvCell(value: unknown): string {
  if (value === null || value === undefined) return "";
  if (typeof value === "number" || typeof value === "boolean" || typeof value === "bigint") {
    return String(value);
  }
  let text = typeof value === "string" ? value : JSON.stringify(value);
  if (FORMULA_START.test(text)) text = `'${text}`;
  return /[",\r\n]/.test(text) ? `"${text.replaceAll('"', '""')}"` : text;
}

/** A header row, then one row per object, with CRLF line ends. */
export function toCsv(columns: string[], rows: Record<string, unknown>[]): string {
  const lines = [columns.map(csvCell).join(",")];
  for (const row of rows) lines.push(columns.map((c) => csvCell(row[c])).join(","));
  return `${lines.join("\r\n")}\r\n`;
}

/** The columns of a set of rows: the keys of the first row, then any a later row adds. */
export function columnsOf(rows: Record<string, unknown>[]): string[] {
  const seen = new Set<string>();
  for (const row of rows) for (const key of Object.keys(row)) seen.add(key);
  return [...seen];
}
